# Ronde G1: religie (idempotent)
from gaten_lib import Ronde,GR
R=Ronde(1);A=R.add;C='Religie'
# --- goden en machten ---
G=[('ysa','Ysa, de Ontvangende Moeder','Hoofdgodin. Oorsprong: oogst- en vruchtbaarheidsgodin van de Rivierstammen (TIJD-rivieren); de Orde maakte haar in 130-210 tot de Moeder die zaad ontvangt en zonen terugneemt. Beeld: een vrouw met open schoot en een lamp in de hand. Functie: maakt de Deelwet en de Ontvangst tot gebed; elke vrouw die ontvangt doet wat Ysa doet. Echt: Ysa bestaat niet als macht; wat gelovigen als haar blik voelen (zegellicht) is de Zegel die eet (GEH-zegel).','FUNC-REL;FUNC-CTRL','GEB-ysa-oogstcultus;FASE-ontvangst;GEH-zegel;RIT-ontvangst'),
('vael','Vael, de Gave-Vader','Tweede godheid: de onzichtbare man wiens vonk in elke gaven-man woont. Ingevoerd in 210 bij de Uitverkorenen om gaven-mannen heilig en dus beheersbaar te maken: een gaven-man is een vat van Vael en dus eigendom van de tempel. Gaven-mannen als Morvane-ir zeggen dat Vael niet bestaat en dat zij zelf de god zijn. Functie: legitimeert gaven-mannen en tegelijk hun afhankelijkheid van de Orde.','FUNC-REL;FUNC-POL','GEB-uitverkorenen;MACHT-gaven-mannen;PER-morvane'),
('wrede-vaders','De Wrede Vaders (demonen)','De zielen van de Vonkkoningen en de mannen van voor de Brand, die volgens de leer in de Leegte wonen en mannen willen terugbrengen tot meerderheid. Elke opstandige man, elke Kharvos-inval en elke weigering heet hun werk. Functie: afschrikking; het verleden als hel. Echt: de mannen van voor de Brand waren echte oorlogvoerders, maar de Zegel is door vrouwen gemaakt; de demonologie verbergt het Offer der Dochters.','FUNC-AFSCHR;FUNC-CTRL','FASE-vonk;FASE-brand;REG-kharvos'),
('leegte-godheid','De Leegte (anti-godheid)','Niet een wezen maar een plaats en een toestand: waar Ysa niet kijkt. Leegteziekte, de uitputting na zaad (MAGIE-kracht-duur), de asvelden rond Ves-Anath. De leer zegt: wie zich onttrekt aan ontvangen, wordt leeg. Functie: maakt onthouding en weigering tot zonde.','FUNC-AFSCHR;FUNC-REL','LICH-leegteziekte;PLEK-RAND-as-wastelands;MAGIE-kracht-duur'),
('dochters-heiligen','De Honderd Dochters (heiligen)','De honderd Zusters die zich in -1 offerden. Officieel: maagden die Ysa smeekten de wrede mannen weg te nemen en door haar werden opgenomen. Echt: zij legden de bloedzegel met hun lichaam (GEB-offer-dochters). Elke Dochter heeft een naam, een feestdag en een relikwie (vinger, haar, een stuk Sterrensteen). Functie: martelaarschap als model voor offers van vrouwen.','FUNC-REL;FUNC-ID','GEB-offer-dochters;GEB-dochteroffer;LICH-dochters'),
('sterrensteen-heilig','De Gevallen Ster','De Sterrensteen-inslag wordt vereerd als de traan van Ysa. Stof ervan zit in merkinkt, wijwater en de Zegel. Echt: het is de bron van de Vonk en van de Zegel (GEB-sterrensteen-inslag); de Orde verbergt dat het steen zelf de magie draagt.','FUNC-REL;FUNC-INFO','GEB-sterrensteen-inslag;VOLK-orrim;LICH-orric-steen')]
for s,o,f,fu,r in G: A(f'GOD-{s}',C,o,f+GR,'goden en machten',r,functie=fu.replace('FUNC-',''))
# --- leer ---
L=[('verlangen-gebed','Leer: verlangen is gebed','Kern van de leer: lust en overgave zijn gebed, en de Ontvangst is de hoogste vorm. Wie vaak en vurig ontvangt, staat dicht bij Ysa. Functie: maakt de zaad-economie vrijwillig en gretig; mensen werken mee omdat het heilig voelt. Echt: elke tempel-Ontvangst voedt de Zegel.','REGEL-seksuele-normen;RIT-ontvangst;GEH-zegel'),
('drie-ringen','Leer: de Drie Ringen van het lichaam','Het lichaam heeft drie ringen: de schoot (ontvangen), het hart (trouw aan het huis) en de mond (de wet uitspreken). Vervorming door gave of ontvangst heet een ring die Ysa tekent: een Ysa-merk. Zo verklaart de leer body horror als heiligheid. Functie: maakt vervorming tot status en ongeschonden lichamen verdacht (DEG-gladden).','LICH-macht-en-lichaam;LICH-ontvangstersbouw;DEG-gladden'),
('teruggenomen-zonen','Leer: de teruggenomen zonen','Ysa neemt 99 van de 100 zonen terug in haar schoot omdat de mannen van voor de Brand wreed waren. Iedere vrouw die een dochter krijgt, krijgt een zoon die Ysa bewaart. Functie: troost en verklaring voor het tekort; verbiedt elke vraag naar een oorzaak. Echt: de Zegel doodt de mannelijke vruchten.','REGEL-verhouding;GEH-zegel;LICH-vergane-zonen'),
('bloedzuiverheid','Leer: zuiverheid van het bloed','Verwantschap is het enige echte vuil; het register is heilig schrift. Wie een register vervalst, vervalst Ysa. Functie: maakt de Orde onmisbaar als bewaker van bloed. Hypocrisie: de tempelfokkerij koppelt juist ingeteelde lijnen (LICH-tempelfokkerij-toestemming).','REGEL-verwantschapstaboe;REGEL-registers-merken;LICH-tempelfokkerij-toestemming'),
('plicht-man','Leer: de plicht van het zaad','Het zaad behoort niet aan de man maar aan Ysa. Een man die zijn zaad weigert of verspilt, steelt van de godin. Functie: maakt melkstallen, rotatie en de Ontladingsplicht vroom. Gaven-mannen staan erboven omdat Vael in hen woont; gewone mannen niet.','MACHT-gewone-mannen;KOE-toestemming;GEB-r10-ontladingsplicht'),
('hiernamaals','Leer: het hiernamaals','Wie in leven veel ontving of gaf, gaat naar de Lampenhof: een eeuwige tempelnacht in Ysa\'s licht. Wie weigerde, gaat naar de Leegte. Gewone mannen gaan naar de Stal van Ysa, waar ze eindelijk vrij zijn (het enige troostbeeld voor mannen). Lijngravers zouden levend in Ysa opgaan.','GOD-leegte-godheid;LIJN-overzicht;MACHT-gewone-mannen'),
('zonde-boete','Leer: zonden en boete','Zeven zonden: verwantschap, register-bedrog, zaadverspilling, weigering van de gave, onthouding zonder gelofte, het noemen van de Wrede Vaders, en vragen naar de oorsprong. Boete: van vasten en de Boeterite (RIT-boeterite) tot het Schandpodium en verbanning naar de rand.','RIT-boeterite;RIT-schandpodium;WET-wetten-straffen'),
('gelofte-onherroepelijk','Leer: de onherroepelijke gelofte','Een gelofte aan Ysa kan niet worden teruggenomen. Deze leer maakt de fictie van voorinstemming mogelijk (LIJN-voorinstemming) en bindt tempelstieren, Lijngravers en Ontvangsters. In de canon: theologische rechtvaardiging van onrecht.','LIJN-voorinstemming;LIJN-recht-orde;REGEL-toestemming-systeem')]
for s,o,f,r in L: A(f'LEER-{s}',C,o,f+GR,'leer: functie eerst',r,functie='REL;CTRL')
# --- geschiedenis van het geloof per fase ---
F=[('overvloed','Rivierstammen en Kroon: Ysa als oogstgodin; vrouwen vieren haar in Zusterhuizen terwijl koningen een vadergod (de Hoornvader) aanbidden. Officieel: een barbaarse tijd zonder ware leer. Echt: de Zusters van Ysa beheren al kruiden, geboorte en Sterrensteen.'),
('vonk','Vonk: vonkkoningen laten zich als god vereren; de Hoornvader wordt vonkgod. De Zusters gaan ondergronds en verzamelen kennis over zaadkracht. Officieel: er waren geen gaven. Echt: de Vonk is de oorsprong van de gave.'),
('brand','Brand: de Zusters smeden het Offer der Dochters; Ysa wordt de godin die mannen wegneemt. Officieel: een wonder. Echt: bloedmagie met Sterrensteen.'),
('noodtoestand','Noodtoestand: de Deelwet wordt als godsgeschenk afgekondigd; het register wordt heilig schrift. Het geloof is sober: rouw en plicht. Officieel: Ysa gaf de wet. Echt: de Zusters schreven haar.'),
('ontvangst','Heilige Ontvangst: zegellicht verschijnt; de Orde (90 als Zusters, 130 als Orde) maakt van plicht een lustgeloof. Vael wordt ingevoerd (210), de Stille Zusters splitsen af. Officieel: Ysa kijkt toe. Echt: de Zegel eet.'),
('markt','Markt: na de Pest wordt geloof handel: aflaten, gunstbrieven, heilige stallen. Sekten groeien in de randen (Vleesgemeente, Wortelbroeders). Officieel: de Pest was straf voor weigering. Echt: overvolle verwante stallen (KOE-pestlink).'),
('barsten','Barsten: lekken en lekgeboorten doen het geloof wankelen; apocalyptische sekten, Morvane-ir\'s bloedkerk en Kharvos-predikers groeien. De Orde reageert met strengere riten en de Zegelbinding. Officieel: beproeving. Echt: de Zegel sterft.')]
for i,(s,f) in enumerate(F,1): A(f'GELOOF-fase-{i}',C,f'Geloof in fase {i} ({s})',f+GR,'geloof per fase',f'FASE-{s};GOD-ysa',functie='REL')
# --- Orde-structuur ---
O=[('rangen','De Orde: rangen in detail','Novice (18-21, leert registers en riten), Ontvangster (de tempelvrouw die met gaven-mannen ontvangt), Hoedster (beheert mannen en stallen), Registratrix (bloed en merk), Drempelmoeder (neemt geloften af van Lijngravers en tempelstieren), Tribunaalmoeder, Moeder (een van de 40 die het Zegelgeheim kennen), Hoge Moeder (Ithrael). Daarnaast de tempelwacht (gewapende zusters) en de Stille Hand (geheime dienst).','ORDE-orde;LIJN-drukmiddelen;RIT-tribunaal-drie'),
('opleiding','De Orde: opleiding','Novicen komen op 18 binnen, vaak als derde dochter van een huis. Drie jaar: registerkunde, kruidenleer, ritueel lichaamswerk, rechtspraak, en (alleen voor Moeders) zegelkunde. Examen: de Ingewijde Nacht, de eerste tempel-Ontvangst onder toezicht, waar de novice zelf kiest of ze Ontvangster wordt of de handen-tak (Hoedster/Registratrix) kiest.','ORDE-orde;RIT-ontvangst'),
('financien','De Orde: financien','Inkomsten: gunstbrieven (verkocht en geveild), tienden op stallen en de Zaadbeurs, tempelgiften, boetes, aflaten (sinds 470), verhuur van Lijngravers, Kluwer-honingwas-monopolie. Uitgaven: tempels, Jongenshoven, tempelwacht. Schuld bij Varenne sinds 610: de Orde leent op toekomstige gunstbrieven; dat is haar zwakke plek.','ECO-geld;HUI-varenne;LIJN-recht-varenne;VOLK-kluwer'),
('conflicten','De Orde: interne conflicten','Drie partijen: de Lampzusters (behoud, meer riten, de Zegelbinding), de Handzusters (bureaucraten en registers, willen een akkoord met Varenne) en de Stille Twijfel (Moeders die weten dat de Zegel sterft en willen bekennen; Hoedster Imra hoort hierbij). Strijd om de opvolging van Ithrael (62).','ORDE-orde;PER-bondgenoten;PER-tegenstanders'),
('stille-hand','De Stille Hand','Geheime dienst van de Orde: zusters die registers vervalsen of corrigeren, lastige vrouwen verdwijnen laten, en Gladden inzetten (DEG-gladden). Ze jagen op Vathren en op Liora na de Wijding van Teo.','DEG-gladden;VOLK-vathren;GEB-r10-quest-begin'),
('tempelwacht','De tempelwacht','Gewapende zusters in rood-goud met hellebaarden waarvan de punt Sterrensteen draagt. Ze bewaken gaven-mannen, Jongenshoven en registers. Ze ontvangen eens per maand Strijdzaad. Verdacht vaak afkomstig uit Kaldra: een kanaal voor Kaldra-invloed.','HUI-kaldra;MACHT-leger;RIT-strijdontvangst')]
for s,o,f,r in O: A(f'ORDE-{s}',C,o,f+GR,'Orde-structuur',r,functie='REL;CTRL;POL')
# --- sekten, ketters, afsplitsingen ---
S=[('SEKTE-stille-zusters','De Stille Zusters (afsplitsing 210)','Zweren mannen af, aanbidden Ysa als de Moeder die niet ontvangt; voortplanting via bewaard zaad en oude magie. Weten dat de Ontvangst iets voedt. Functie voor de wereld: tegenwicht, kennisbewaarders, verzetsbasis (LIJN-verzet).','REG-stille;GEB-schisma-stilte;LIJN-verzet','ketterij'),
('SEKTE-vleesgemeente','De Vleesgemeente','Randsekte (sinds 480) die vervorming aanbidt: wie het meest vervormd is staat dichtst bij Ysa. Vrijwillige mutatieriten tussen volwassenen, walglust als gebed (VOOR-walglust), uitstalling van het eigen lichaam. Kink-plek: de Vleestempels in Hal-Neth. Gevaar: ronselt Leegtezieken en verkoopt hen aan Varenne.','VOOR-walglust;LICH-mutatie-ritueel;PLEK-RAND-verlaten-fokstal','sekte'),
('SEKTE-wortelbroeders','De Wortelbroeders','Gewone mannen en hoeders die de Lijngravers als heiligen zien die Ysa levend bereiken; ze willen zelf Lijngraver worden. Gevaarlijk omdat ze de leugen van de Orde gelovig omarmen. Tegenspeler van de Losmakers.','LIJN-overzicht;LIJN-hoeders;LIJN-verzet','sekte'),
('SEKTE-vaderlingen','De Vaderlingen','Ondergrondse mannencultus in de stallen: aanbidden de Wrede Vaders als bevrijders en dromen van een wereld van 1 op 2. Contacten met Kharvos-predikers. Tekens in stalbalken gekrast. Bram kent hun teken.','GOD-wrede-vaders;KOE-opstand;PER-gewone-mannen;REG-kharvos','ketterij'),
('SEKTE-bloedkerk','De Bloedkerk van Lisk','De kerk van Morvane-ir: hij is Vael zelf, zijn bloed is sacrament; gebonden vrouwen zijn priesteressen. Rituelen: Bloedverbinding als doop. Functie: maakt zijn harem en zijn leger fanatiek trouw.','PER-morvane;RIT-bloedverbinding;GEB-bloednacht-788','ketterij'),
('SEKTE-zonkerk','De Zonkerk van Qesh','Khaled-Ir laat zich vereren als zoon van de zon; Ysa is daar een maangodin die de zon dient. Ishvar-invloed: trouw voor het leven telt meer dan ontvangen. De Orde noemt het afvalligheid maar handelt ermee.','PER-khaled;HUI-qesh;VOLK-ishvar','afsplitsing'),
('SEKTE-annalisten','De Annalisten','Ketters die de echte geschiedenis zoeken: geleerden, Aelthir-luisteraars en verdreven Registratrices. Hun stelling: Ysa nam niemand terug; iemand heeft het gedaan. Worden verbrand als ze worden gevonden. Bewaren afschriften in Myrrhen-schimmelnetten.','GEB-r10-vervalste-annalen;VOLK-aelthir;VOLK-myrrhen','ketterij'),
('SEKTE-lampenwakers','De Lampenwakers','Apocalyptische beweging (sinds 760): de lekken zijn het einde; wie in de laatste nacht ontvangt, gaat mee naar de Lampenhof. Massale nachtriten op pleinen, uitputting, binding. Voor de Orde handig en gevaarlijk tegelijk.','FASE-barsten;GEB-zegel-verzwakt;RIT-nacht-duizend-lampen','sekte'),
('SEKTE-mael','Het Mael-schisma','Oud schisma (zie GEB-r10-mael-schisma): leert dat ook vrouwen elkaar zaadkracht kunnen geven door Ysa\'s adem; vrouwenliefde als sacrament. Overleeft als gedoogde orde in Ambergaard.','GEB-r10-mael-schisma;VOOR-vrouwenliefde;REG-ambergaard','afsplitsing')]
for code,o,f,r,t in S: A(code,C,o,f'Type: {t}. '+f+GR,'sekten en ketters',r,functie='REL;POL')
# --- kalender en feestdagen ---
A('KAL-kalender',C,'De Ysa-kalender','Jaartelling vanaf de Zegel (jaar 0; nu 801). Een jaar heeft 13 manen van 28 dagen plus de Lege Dag. Week van 7 dagen; de zevende is Ontvangstdag. Manen heten naar ontvangsten en oogst (Zaaimaan, Lampmaan, Stilmaan, Melkmaan, Bloedmaan, Rotmaan, Oogstmaan ...). Functie: maakt het ritme van rotatie (MACHT) en tempelnachten tot natuur.'+GR,'kalender','GEB-zegel;RIT-ontvangst',functie='REL;CTRL')
FD=[('lege-dag','De Lege Dag','Jaarwisseling: een dag zonder ontvangen, waarop de Leegte heerst. Iedereen vast; deuren dicht; gewone mannen worden opgesloten. Echt: de enige dag dat de Zegel niet wordt gevoed; Vathren voelen hem dan zwakken.','GOD-leegte-godheid;VOLK-vathren'),
('dochterdag','Dochtersnacht (honderd nachten)','Honderd nachten verspreid over het jaar, elk voor één Dochter, met relikwieprocessie en een collectieve Ontvangst in haar naam.','GOD-dochters-heiligen;RIT-ontvangst'),
('lampenfeest','Nacht van Duizend Lampen','Midzomer: alle tempels open, gaven-mannen in rotatie, openbare ontvangsten. Grootste voeding van de Zegel van het jaar.','RIT-nacht-duizend-lampen;PLEK-LICH-lampenfeest'),
('wijdingsdag','Wijdingsdag','Eens per jaar in elke Jongenshof: jongemannen van 18 worden getest op de gave. Geen seksuele rite; feest van de moeders. Teo werd gewijd op Wijdingsdag 801.','RIT-wijding;GEB-teo-801'),
('oogstnacht','Oogstnacht (Ambergaard)','De oude Ysa van de oogst: het Oogstbed in de stalhuizen, graanoffers, dans. Het meest volkse feest.','RIT-oogstbed;REG-ambergaard'),
('stilmaan','Stilmaan','Een maand van onthouding voor novicen en rouw om de teruggenomen zonen; begraafriten voor doodgeboren jongens. Voor de Stille Zusters de heiligste maand.','LEER-teruggenomen-zonen;SEKTE-stille-zusters'),
('melkfeest','Melkzegen-feest','De stallen worden gezegend, gewone mannen krijgen een dag rust en bloemenkransen; daarna een melkrite. Voor mannen het dubbelzinnigste feest.','RIT-melkzegen;RIT-melkrite;KOE-melkos'),
('zonnefeest','Zonnefeest van Qesh','Midwinterfeest van Khaled-Ir: de harem dingt om zijn gunst; Ishvar vieren tegelijk hun Twee-gelofte.','PER-khaled;RIT-tweegelofte')]
for s,o,f,r in FD: A(f'FEEST-{s}',C,o,f+GR,'feestdagen',r+';KAL-kalender',functie='REL')
# --- heilige plekken en voorwerpen ---
H=[('PLEK-HEILIG-zeven-eilanden','Tempel der Zeven Eilanden (Saelith)','Hoofdtempel; onder het altaar loopt de sterkste zegellijn van het land. Ontvangstzaal, registerkelders, de troon van Ithrael.','REG-saelith;PLEK-LICH-ontvangstzaal'),
('PLEK-HEILIG-ves-anath','Ves-Anath (verboden heiligdom)','Waar de Dochters stierven; officieel de plek waar Ysa neerdaalde, verlaten sinds de ontruiming. Bedevaart verboden.','PLEK-LICH-ves-anath;GEB-ves-anath-ontruimd'),
('PLEK-HEILIG-ijsgraf','Klooster Ijsgraf','Klooster in Hoogvrouwe met de grootste relikwieschat (vingers van Dochters) en een Sterrensteenader.','REG-hoogvrouwe'),
('PLEK-HEILIG-inslagkrater','De Krater van de Traan','Waar de Sterrensteen viel (Rosse Woestijn); Orrim-gebied; de Orde oogst er steen.','GOD-sterrensteen-heilig;VOLK-orrim;REG-rosse')]
for code,o,f,r in H: A(code,C,o,f+GR,'heilige plekken',r,functie='REL')
V=[('VOORW-register','Het Grote Register','Heilig schrift en macht: boeken op Sterrensteen-perkament met alle bloedlijnen; het origineel ligt onder Saelith. Vervalsingen zijn er al eeuwen in.','REGEL-registers-merken;LEER-bloedzuiverheid'),
('VOORW-lampen','Ysa-lampen','Olielampen met een Sterrensteen-splinter; ze gloeien zwak bij Ontvangst. Echt: ze tonen zegellicht, dus ze zijn lekdetectoren.','GOD-ysa;LICH-zegeltong'),
('VOORW-relikwieen','Relikwieen van de Dochters','Gemummificeerde vingers, haar en tanden in Sterrensteen-schrijnen; in feite zegelankers. Wie er een steelt, verzwakt de lokale zegellijn.','GOD-dochters-heiligen'),
('VOORW-gunstbrief','De gunstbrief als heilig voorwerp','Gezegeld met het lampenzegel; wie hem verbrandt, verliest haar plaats bij Ysa. Ook valuta (ECO-geld).','ECO-geld'),
('VOORW-halsband','De gewijde halsband','Gewone mannen dragen een door de Orde gezegende band met huiswapen; hem afdoen is zonde.','CUL-kleding;RIT-halsbandwissel')]
for code,o,f,r in V: A(code,C,o,f+GR,'heilige voorwerpen',r,functie='REL;ID')
# --- volksgeloof vs Orde ---
A('GELOOF-volk-vs-orde',C,'Geloof van gewone mensen versus de Orde','Gewone vrouwen geloven praktisch: lampjes, zaad op de drempel, gebeden voor een zoon, kruidenvrouwen, Dochter-amuletten (CUL-eten-kunst-bijgeloof). De Orde gelooft in registers en macht; veel Moeders zijn zelf ongelovig. Gewone mannen geloven in de Stal van Ysa en heimelijk in de Vaderlingen. Gaven-mannen geloven vooral in zichzelf. Functie: het volksgeloof draagt het systeem omdat het troost geeft; de Orde-leer draagt het omdat het straft.'+GR,'volk versus Orde','CUL-eten-kunst-bijgeloof;SEKTE-vaderlingen;ORDE-conflicten',functie='REL;CTRL')
A('GELOOF-officieel-vs-echt',C,'Officiele versus echte geschiedenis van het geloof','Officieel: Ysa nam de wrede mannen weg, gaf de Deelwet, kijkt via zegellicht en zendt gaven vanaf 210. Echt: vrouwen legden in -1 met bloed en Sterrensteen de Zegel; de Deelwet is mensenwerk; zegellicht is de Zegel die eet; de gave bestaat al sinds de Vonk; de annalen zijn vervalst (GEB-r10-vervalste-annalen). Wie het weet: 40 Moeders, de Aelthir (zwijgend), Stille Zusters (half), Annalisten (zoekend).'+GR,'officieel vs echt','GEH-zegel;GEH-wie-weet-wat;GEB-r10-vervalste-annalen;SEKTE-annalisten',functie='REL;INFO')
A('GELOOF-functie',C,'Waarom het geloof onmisbaar is (functie)','Het geloof doet vier dingen die niets anders kan: (1) het maakt de zaad-economie vrijwillig (lust als gebed), (2) het maakt het lichaam beheersbaar (vervorming als Ysa-merk, gelofte als onherroepelijk), (3) het voedt de Zegel via tempel-Ontvangsten, (4) het verbiedt vragen naar de oorsprong. Zonder geloof: de Ontvangsten worden markt (Varenne wint), de Zegel verhongert sneller, en de vraag waarom er geen zonen zijn wordt gesteld.'+GR,'functie eerst','FUNC-REL;GEH-zegel;LEER-verlangen-gebed;LEER-drie-ringen',functie='REL;CTRL;ECO')
# --- geloof per volk ---
VK=[('aelthir','Vereren geen Ysa; kennen haar als oogstgeest van mensen. Hun geloof: het Lange Geheugen, voorouders in boomringen. Zwijgen over de Zegel uit schuld: zij waren erbij.'),
('karrûk','Vuurgeloof: de Kookgeest die in hun huid woont; strijd is gebed. Ysa is voor hen de koude vrouw van de vijand.'),
('dhurn','Steenvaders en de Diepe Moeder van de berg; Sterrensteen is heilig en mag alleen door gildemeesters bewerkt. Verdragen de Orde uit handel.'),
('sael-mor','Getijdengeloof: de zee is Ysa\'s eigen schoot, buiten bereik van de tempels; elke haven een andere partner, elk getij een gebed.'),
('grauwen','Geloven dat Ysa hen heeft verstoten; een stil geloof van zorg en de Ontsluiering als sacrament van gezien worden.'),
('ishvar','Geen goden; een ethiek van de Twee-gelofte en de zon als getuige. Voor de Orde de grootste ketterij: zij hebben geen Zegel nodig.'),
('vathren','Voelen de Zegel als een hartslag en noemen hem het Grote Hart; ze weten dat het geen godin is maar iets dat leeft en honger heeft.'),
('kluwer','Korfgeloof: de Broedmoeder is godin in levende lijve; was en honing zijn sacrament; Ysa heet bij hen de Valse Broedmoeder.'),
('myrrhen','Het Netwerk onthoudt alle doden; sterven is opgenomen worden. Geen goden, wel heilige rot. Bewaren Annalisten-afschriften.'),
('oevrin','Paaigeloof: de Slikmoeder in de diepe poel; voortplanting buiten het lichaam is voor hen heilig en spot met de Zegel.'),
('tharn','Rouwgeloof van een uitstervend volk: elk kind een heilige; ze eren de dijken die hun voorouders bouwden als tempels.'),
('orrim','Vereren de Gevallen Ster als moeder van wie ze zijn; zien de Orde-oogst als heiligschennis en moord.'),
('skerra','Windgeloof; vonkkoningen zijn hun scheppers en hun demonen tegelijk. Officieel tot Ysa bekeerd, als koeriers van de Orde.'),
('ves-lethi','Spiegelgeloof: elke vorm is waar en geen vorm is blijvend. De Orde ziet hen als belichaming van de Wrede Vaders (vrouw wordt man).')]
for v,f in VK:
  vc='VOLK-'+v
  A(f'GELOOF-volk-{v.replace("û","u")}',C,f'Geloof van de {v.capitalize()}',f+' Functie: bepaalt hoe dit volk zich tot de Orde en het zaadsysteem verhoudt.'+GR,'geloof per volk',f'{vc};GOD-ysa',functie='REL;DIPLO')
RG=[('saelith','Orthodox en vroom; registers heilig; Lampzusters sterk.'),('ambergaard','Volks en nuchter: Oogst-Ysa, Mael-zusters, stalgebeden.'),('hoogvrouwe','Krijgsgeloof: Dochters als krijgsheiligen; relikwieen in Ijsgraf.'),('zoutkust','Los en handelaarsgeloof; aflaten te koop; Sael-mor-getijgeloof.'),('groenmuil','Oud en wantrouwig; Kluwer- en Myrrhen-invloed; Annalisten verstoppen zich hier.'),('rosse','Zonkerk van Qesh; Ishvar zonder goden; Orrim-steengeloof.'),('kharvos','Hoornvader-geloof: de man is god, vrouwen zijn offer; Vaderlingen-predikers komen hier vandaan.'),('stille','Stille Ysa die niet ontvangt; geen tempelnachten.')]
for g,f in RG: A(f'GELOOF-reg-{g}',C,f'Geloof in {g.capitalize()}',f+GR,'geloof per regio',f'REG-{g};GOD-ysa',functie='REL')
# --- functie per systeem en rituelen ---
A('GELOOF-dient-zaad',C,'Hoe geloof de zaad-economie dient','Gunstbrieven zijn heilig en dus waardevast; tienden op stallen; aflaten voor verspild zaad; de Ontladingsplicht als gebod. Rituelen: RIT-ontvangst, RIT-melkrite, RIT-veiling, RIT-zaadcontract.'+GR,'functie economie','ECO-geld;RIT-ontvangst;RIT-melkrite;RIT-veiling;RIT-zaadcontract',functie='ECO;REL')
A('GELOOF-dient-lichaam',C,'Hoe geloof het lichaam dient','Vervorming = Ysa-merk (LEER-drie-ringen); de Wijding als oordeel over het mannenlichaam; Lijngraver-gelofte maakt opgegeten worden tot heiligheid. Rituelen: RIT-wijding, RIT-zegelvoeding, RIT-boeterite.'+GR,'functie lichaam','LEER-drie-ringen;RIT-wijding;RIT-zegelvoeding;LIJN-overzicht',functie='CTRL;REL')
A('GELOOF-dient-zegel',C,'Hoe geloof de Zegel dient','Elke tempel-Ontvangst draagt kracht af aan de Zegel; het geloof zorgt dat er duizenden per nacht zijn. Lampenfeesten, de Zevenvoudige Ontvangst en straks de Zegelbinding zijn voedingsrituelen. Rituelen: RIT-zegelvoeding, RIT-zegelbinding, RIT-nacht-duizend-lampen, RIT-zevenvoudige-ontvangst.'+GR,'functie Zegel','GEH-zegel;RIT-zegelvoeding;RIT-zegelbinding;RIT-zevenvoudige-ontvangst',functie='REL;CTRL')
